import torch.nn as nn
from torch.utils.cpp_extension import load_inline

# Define the vectorized CUDA kernel for matrix multiplication
matmul_source = """
#include <torch/extension.h>
#include <cuda_runtime.h>

#define TILE_SIZE 32
#define REG_TILE 4

__global__ void matmul_kernel(const float* A, const float* B, float* C, int N) {
    // Shared memory for tiles
    __shared__ float As[TILE_SIZE][TILE_SIZE];
    __shared__ float Bs[TILE_SIZE][TILE_SIZE];

    // Thread and block indices
    int tx = threadIdx.x;
    int ty = threadIdx.y;
    int bx = blockIdx.x;
    int by = blockIdx.y;

    // Register tiles for accumulation
    float c_reg[REG_TILE][REG_TILE] = {0};

    // Calculate base indices for this thread
    int base_row = by * TILE_SIZE + ty * REG_TILE;
    int base_col = bx * TILE_SIZE + tx * REG_TILE;

    // Loop over tiles
    for (int t = 0; t < (N + TILE_SIZE - 1) / TILE_SIZE; ++t) {
        // Load A tile into shared memory
        for (int i = 0; i < REG_TILE; ++i) {
            int row = by * TILE_SIZE + ty * REG_TILE + i;
            int col = t * TILE_SIZE + tx;
            if (row < N && col < N) {
                As[ty * REG_TILE + i][tx] = A[row * N + col];
            } else {
                As[ty * REG_TILE + i][tx] = 0.0f;
            }
        }

        // Load B tile into shared memory
        for (int i = 0; i < REG_TILE; ++i) {
            int row = t * TILE_SIZE + ty;
            int col = bx * TILE_SIZE + tx * REG_TILE + i;
            if (row < N && col < N) {
                Bs[ty][tx * REG_TILE + i] = B[row * N + col];
            } else {
                Bs[ty][tx * REG_TILE + i] = 0.0f;
            }
        }

        __syncthreads();

        // Compute using register tiles
        for (int k = 0; k < TILE_SIZE; ++k) {
            float a_reg[REG_TILE];
            float b_reg[REG_TILE];

            // Load from shared memory to registers
            #pragma unroll
            for (int i = 0; i < REG_TILE; ++i) {
                a_reg[i] = As[ty * REG_TILE + i][k];
                b_reg[i] = Bs[k][tx * REG_TILE + i];
            }

            // Compute outer product
            #pragma unroll
            for (int i = 0; i < REG_TILE; ++i) {
                #pragma unroll
                for (int j = 0; j < REG_TILE; ++j) {
                    c_reg[i][j] += a_reg[i] * b_reg[j];
                }
            }
        }

        __syncthreads();
    }

    // Write results back to global memory
    for (int i = 0; i < REG_TILE; ++i) {
        for (int j = 0; j < REG_TILE; ++j) {
            int row = base_row + i;
            int col = base_col + j;
            if (row < N && col < N) {
                C[row * N + col] = c_reg[i][j];
            }
        }
    }
}

torch::Tensor matmul_cuda(torch::Tensor A, torch::Tensor B) {
    auto N = A.size(0);
    auto C = torch::zeros({N, N}, A.options());

    dim3 block(TILE_SIZE / REG_TILE, TILE_SIZE / REG_TILE);
    dim3 grid((N + TILE_SIZE - 1) / TILE_SIZE, (N + TILE_SIZE - 1) / TILE_SIZE);

    matmul_kernel<<<grid, block>>>(
        A.data_ptr<float>(),
        B.data_ptr<float>(),
        C.data_ptr<float>(),
        N
    );

    return C;
}
"""

